export const HOME_WIDGET_VERSION = 13;
export const HOME_WIDGET_URI = `ui://home/listings-and-detail-v${HOME_WIDGET_VERSION}.html`;
export type HomeMapPoint = { latitude: number; longitude: number };

export function homeMapProject(latitude: number, longitude: number, zoom: number): { x: number; y: number } {
  const size = Math.pow(2, zoom) * 256, sin = Math.sin(latitude * Math.PI / 180);
  return { x: (longitude + 180) / 360 * size, y: (.5 - Math.log((1 + sin) / (1 - sin)) / (4 * Math.PI)) * size };
}
export function homeMapLayout(points: HomeMapPoint[], width: number, height: number): { zoom: number; left: number; top: number; pins: Array<{ x: number; y: number }> } {
  const w = Math.max(1, width), h = Math.max(1, height); let zoom = 15, projected: Array<{x:number;y:number}> = [];
  for (; zoom > 4; zoom--) { projected = points.map(p => homeMapProject(p.latitude,p.longitude,zoom)); const xs=projected.map(p=>p.x),ys=projected.map(p=>p.y); if(Math.max(...xs)-Math.min(...xs)<=w-96&&Math.max(...ys)-Math.min(...ys)<=h-96) break; }
  projected=points.map(p=>homeMapProject(p.latitude,p.longitude,zoom)); const xs=projected.map(p=>p.x),ys=projected.map(p=>p.y),left=(Math.min(...xs)+Math.max(...xs))/2-w/2,top=(Math.min(...ys)+Math.max(...ys))/2-h/2;
  return {zoom,left,top,pins:projected.map(p=>({x:p.x-left,y:p.y-top}))};
}
export type HomePinBox = { x: number; y: number; width: number; height: number };
/** Marks only price labels that would overlap an earlier label at the current map position. */
export function homePinCollisions(boxes: HomePinBox[], gap = 4): boolean[] {
  const shown: HomePinBox[] = [];
  return boxes.map((box) => {
    const overlaps = shown.some((other) => Math.abs(box.x - other.x) < (box.width + other.width) / 2 + gap && Math.abs(box.y - other.y) < (box.height + other.height) / 2 + gap);
    if (!overlaps) shown.push(box);
    return overlaps;
  });
}
export function homePinLabel(price: unknown, rentalFrequency?: unknown, locale="en-GB"): string|null { const n=Number(price); if(!Number.isFinite(n))return null; if(rentalFrequency||n<10000)return new Intl.NumberFormat(locale,{style:"currency",currency:"GBP",maximumFractionDigits:0}).format(n); if(n>=1000000)return`£${(n/1000000).toFixed(n%1000000?1:0)}m`; return`£${Math.round(n/1000)}k`; }
export function humaniseDaysListed(value: unknown): string|null { const days=Number(value); if(!Number.isFinite(days)||days<0)return null; if(days<1)return"Listed today"; if(days<14){const n=Math.max(1,Math.round(days));return`${n} day${n===1?"":"s"}`;} if(days<84){const n=Math.max(2,Math.round(days/7));return`${n} weeks`;} const n=Math.max(3,Math.round(days/30.4375));return`${n} months`; }

